import {guideAnswers} from './guide-answers.mjs';
import {socialMeta} from './social-meta.mjs';
import {blogIndex} from './blog-index.mjs';
import {sources} from './blog-content/sources.mjs';
import {tools,icon} from './catalog.mjs';
import {escapeHTML as e} from './core.mjs';
export {blogIndex};
export const blogCategories=[['images','Images'],['creative','Creative'],['documents','PDF & QR'],['learning','Learning'],['planning','Everyday planning'],['security','Security & code'],['money','Money arithmetic'],['business','Small business'],['nepal','Nepal']];
const displayDate=value=>new Intl.DateTimeFormat('en-GB',{day:'numeric',month:'long',year:'numeric',timeZone:'UTC'}).format(new Date(value+'T00:00:00Z'));
const articleURL=slug=>'./blog/'+slug+'/';
const categoryName=id=>blogCategories.find(c=>c[0]===id)?.[1]||'Guides';
export const blogCard=p=>`<article class="blog-card"><span class="blog-label">${e(categoryName(p.category))} · ${p.minutes} min read</span><h2><a href="${articleURL(p.slug)}">${e(p.title)}</a></h2><p>${e(p.summary)}</p><a class="blog-read" href="${articleURL(p.slug)}">Read the guide ${icon('arrow')}</a></article>`;
export function blogHTML(page,article){
 if(page.type==='article')return article?articleHTML(article):'<div class="page-heading"><p role="status">Opening your guide…</p></div>';
 const list=blogIndex.filter(p=>page.type!=='blogCategory'||p.category===page.id);
 return `<nav class="tool-breadcrumb" aria-label="Breadcrumb"><a href="./">Home</a><span>/</span><a href="./blog/">Guides</a>${page.type==='blogCategory'?'<span>/</span><span aria-current="page">'+e(categoryName(page.id))+'</span>':''}</nav><div class="page-heading blog-heading"><div class="eyebrow"><span class="dot"></span>THE NEPOCORE FIELD NOTES</div><h1>${page.type==='blogCategory'?e(categoryName(page.id))+' guides':'A little know-how.<br>More possibility.'}</h1><p>Practical walkthroughs, worked examples and honest limits.<br>Make the most of the tools you use every day.</p><span class="collection-badge">${list.length} original guides</span></div><form class="blog-search" data-blog-search role="search"><label for="guide-query">Find a guide</label><div><input id="guide-query" type="search" placeholder="Try PDF, budget, QR or Nepali…"><button class="btn primary">Search guides</button></div></form><nav class="blog-categories" aria-label="Guide topics"><a class="chip ${page.type==='blog'?'active':''}" href="./blog/">All guides</a>${blogCategories.map(([id,name])=>`<a class="chip ${page.id===id?'active':''}" href="./blog/category/${id}/">${e(name)}</a>`).join('')}</nav><p class="count-label" data-guide-count aria-live="polite">${list.length} guides</p><div class="blog-grid" data-guide-grid>${list.map(blogCard).join('')}</div><aside class="editorial-note"><strong>Clear methods. No invented expertise.</strong><p>These original guides were drafted with AI assistance from the tool behavior and linked references. They are general instructions, not claims of professional review. <a href="./editorial-policy/">How we prepare and correct content ↗</a></p></aside>`;
}
export function articleHTML(post){const meta=blogIndex.find(p=>p.slug===post.slug),paragraphs=items=>(items||[]).map(p=>'<p>'+e(p)+'</p>').join('');const related=blogIndex.filter(p=>p.category===post.category&&p.slug!==post.slug).slice(0,3);return `<article class="blog-article" data-blog-article="${e(post.slug)}"><nav class="tool-breadcrumb" aria-label="Breadcrumb"><a href="./">Home</a><span>/</span><a href="./blog/">Guides</a><span>/</span><a href="./blog/category/${post.category}/">${e(categoryName(post.category))}</a></nav><header class="article-header"><span class="blog-label">${e(categoryName(post.category))}</span><h1>${e(post.title)}</h1><p class="article-deck">${e(post.summary)}</p><div class="article-meta">By <a href="./about/">Nepocore</a><span>Published <time datetime="${meta.date}">${displayDate(meta.date)}</time></span><span>Updated <time datetime="${meta.updated||meta.date}">${displayDate(meta.updated||meta.date)}</time></span><span>${meta.minutes} min read</span></div></header><div class="article-layout"><aside class="article-toc"><strong>In this guide</strong><ol><li><a href="${articleURL(post.slug)}#quick-answer">Quick answer</a></li>${post.sections.map((s,i)=>`<li><a href="${articleURL(post.slug)}#guide-section-${i+1}">${e(s.title)}</a></li>`).join('')}</ol><a class="blog-read" href="./blog/">← All guides</a><a class="blog-read" href="./blog/${e(post.slug)}/index.md" type="text/markdown">Plain text version ↗</a></aside><div class="article-body"><section class="quick-answer" id="quick-answer" aria-labelledby="quick-answer-title"><span class="eyebrow">THE USEFUL PART, UP FRONT</span><h2 id="quick-answer-title">Quick answer</h2><p>${e(guideAnswers[post.slug])}</p><a href="${articleURL(post.slug)}#guide-references">Check the references and method notes ↓</a></section>${post.sections.map((s,i)=>`<section id="guide-section-${i+1}"><h2>${e(s.title)}</h2>${paragraphs(s.paragraphs)}${s.list?'<ol>'+s.list.map(x=>'<li>'+e(x)+'</li>').join('')+'</ol>':''}${s.table?'<div class="article-table"><table><thead><tr>'+s.table.headers.map(h=>'<th scope="col">'+e(h)+'</th>').join('')+'</tr></thead><tbody>'+s.table.rows.map(r=>'<tr>'+r.map(x=>'<td>'+e(x)+'</td>').join('')+'</tr>').join('')+'</tbody></table></div>':''}${paragraphs(s.paragraphsAfter)}</section>`).join('')}<aside class="article-tools"><span class="eyebrow">PUT IT INTO PRACTICE</span><h2>Your next useful step</h2>${post.tools.map(id=>{const t=tools.find(t=>t.id===id);return `<a href="./tools/${id}/">${icon(t.icon)}<span><strong>${e(t.title)}</strong><small>${e(t.description)}</small></span>${icon('arrow')}</a>`;}).join('')}</aside><section class="article-sources" id="guide-references"><h2>References & method notes</h2><p>The linked references explain the underlying formats, APIs or methods. Worked examples and instructions are original to this guide; a reference is not an endorsement of Nepocore.</p><ul>${post.sources.map(id=>`<li><a href="${e(sources[id][1])}" target="_blank" rel="noopener noreferrer">${e(sources[id][0])} ↗</a></li>`).join('')}</ul></section><aside class="editorial-note"><p>Prepared with AI assistance. No specialist, clinical or financial review is claimed. Check important outputs and current recipient requirements. <a href="./editorial-policy/">Editorial policy</a> · <a href="mailto:admin@nepocore.com?subject=${encodeURIComponent('Correction: '+post.title)}">Suggest a correction</a></p></aside></div></div></article>${related.length?'<section class="related-guides"><div class="section-head"><h2>Keep a little curiosity.</h2><a href="./blog/">All guides ↗</a></div><div class="blog-grid">'+related.map(blogCard).join('')+'</div></section>':''}`;}
export function blogSchema(page,root){const base=new URL(root),url=new URL(page.type==='article'?'blog/'+page.id+'/':page.type==='blogCategory'?'blog/category/'+page.id+'/':'blog/',base).href;if(page.type==='article'){const p=blogIndex.find(p=>p.slug===page.id);return [{'@type':'BlogPosting','@id':url+'#article',mainEntityOfPage:url,url,headline:p.title,description:p.summary,abstract:guideAnswers[p.slug],datePublished:p.date,dateModified:p.updated||p.date,inLanguage:'en',author:{'@type':'Organization',name:'Nepocore',url:new URL('about/',base).href},publisher:{'@id':new URL('#organization',base).href},image:socialMeta('blog/'+p.slug+'/',p.title,base).image,isAccessibleForFree:true},{'@type':'BreadcrumbList',itemListElement:[{'@type':'ListItem',position:1,name:'Home',item:base.href},{'@type':'ListItem',position:2,name:'Guides',item:new URL('blog/',base).href},{'@type':'ListItem',position:3,name:p.title,item:url}]}];}const list=blogIndex.filter(p=>page.type!=='blogCategory'||p.category===page.id);return [{'@type':'CollectionPage',url,name:page.type==='blogCategory'?categoryName(page.id)+' guides':'Nepocore practical guides',mainEntity:{'@type':'ItemList',numberOfItems:list.length,itemListElement:list.map((p,i)=>({'@type':'ListItem',position:i+1,name:p.title,url:new URL('blog/'+p.slug+'/',base).href}))}}];}
const loaders={learning:()=>import('./blog-content/learning.mjs'),images:()=>import('./blog-content/images.mjs'),documents:()=>import('./blog-content/documents.mjs'),planning:()=>import('./blog-content/planning.mjs'),security:()=>import('./blog-content/security.mjs'),business:()=>import('./blog-content/business.mjs')};
export async function loadArticle(slug){const p=blogIndex.find(p=>p.slug===slug);if(!p)throw Error('Guide not found.');return (await loaders[p.file]()).default.find(p=>p.slug===slug);}
